func matchNATSSubjectFilter(subject, filter string) bool {
	filter = strings.TrimSpace(filter)
	if filter == "" || filter == ">" {
		return true
	}
	if !strings.ContainsAny(filter, "*>") {
		return strings.Contains(subject, filter)
	}
	subTokens := strings.Split(subject, ".")
	patTokens := strings.Split(filter, ".")
	for i, pat := range patTokens {
		if pat == ">" {
			return i < len(subTokens)
		}
		if i >= len(subTokens) {
			return false
		}
		if pat != "*" && pat != subTokens[i] {
			return false
		}
	}
	return len(subTokens) == len(patTokens)
}

